","import { useCallback, useMemo } from 'react';
import { useBaseAPI } from './useBaseAPI.js';

/**
 * Notifications API hook
 * Provides simple notification management functionality
 *
 * @returns Notifications API interface with state and methods
 *
 * @example
 * ```typescript
 * const notifications = useNotificationsAPI();
 * notifications.addNotification({ type: 'success', message: 'Saved!' });
 * notifications.removeNotification(0);
 * notifications.clearNotifications();
 * ```
 */
function useNotificationsAPI() {
    // const [notifications, setNotifications] = useState<Notification[]>([]);
    const { state, setState } = useBaseAPI({
        initialState: {
            notifications: []
        }
    });
    /**
     * Add a single notification
     */
    const addNotification = useCallback((notification) => {
        setState(prev => ({ ...prev, notifications: [...prev.notifications, notification] }));
    }, []);
    /**
     * Add multiple notifications
     */
    const addNotifications = useCallback((newNotifications) => {
        setState(prev => ({ ...prev, notifications: [...prev.notifications, ...newNotifications] }));
    }, []);
    /**
     * Remove a notification by index
     */
    const removeNotification = useCallback((index) => {
        setState(prev => ({ ...prev, notifications: prev.notifications.filter((_, i) => i !== index) }));
    }, []);
    /**
     * Clear all notifications
     */
    const clearNotifications = useCallback(() => {
        setState({ notifications: [] });
    }, []);
    return useMemo(() => ({
        // State
        notifications: state.notifications,
        // Methods
        addNotification,
        addNotifications,
        removeNotification,
        clearNotifications
    }), [state.notifications, addNotification, addNotifications, removeNotification, clearNotifications]);
}

