     * @param replyType The reply type. Must be either "reply" or "replyAll"
     */
    const replyToEmail = useCallback((emailSysId, replyType = 'reply') => {
        const emailAction = {
            ...getNewCompositionEmailInfo(),
            replyId: emailSysId,
