","import { useState, useEffect } from 'react';
import userSessionProvider from './data_providers/userSessionProvider.js';
import deviceInfoProvider from './data_providers/deviceInfoProvider.js';
import sysPropsProvider from './data_providers/sysPropsProvider.js';
import hardcodedProvider from './data_providers/hardcodedProvider.js';
import computedProvider from './data_providers/computedProvider.js';

const providers = [
  hardcodedProvider,
  userSessionProvider,
  deviceInfoProvider,
  sysPropsProvider,
  computedProvider
];

//not in query  com.glide.amb.session.logout  sys prop contains value for  session.output.properties.ambSessionLogout

const setUxGlobals = globals => {
  window.ux_globals = globals;
};

const getUxGlobals = () => {
  return window?.ux_globals || {};
};

const getUXGlobalsData = async () => {
  return new Promise(resolve => {
    Promise.allSettled(providers.map(p => p.provider)).then(results => {
      let globals = {...getUxGlobals(), isUxGlobalsDynamicallyLoaded: true};
      for (let providerIndex = 0; providerIndex < results.length; providerIndex++) {
        const result = results[providerIndex];
        if (result.status === 'fulfilled') {
          const mapper = providers[providerIndex].mapper;
          globals = mapper(globals, result.value);
        }
      }

      resolve(globals);
    });
  });
};

const useIsUXGlobalsLoading = () => {
  const [isGlobalsLoading, setIsGlobalsLoading] = useState(true);

  useEffect(() => {
    if (getUxGlobals()?.isUxGlobalsDynamicallyLoaded) {
      setIsGlobalsLoading(false);
    } else {
      const loadGlobals = async () => {
        try {
          setUxGlobals(await getUXGlobalsData());
          setIsGlobalsLoading(false);
        } catch (error) {
          console.error('Error loading UX globals:', error);
          // Still set to true to render despite error
          setIsGlobalsLoading(false);
        }
      };

      loadGlobals();
    }
  }, []);

  return isGlobalsLoading;
};

