","import React from "react";
import { RecordProvider } from "@servicenow/react-components/RecordContext";
import { FormActionBar } from "@servicenow/react-components/FormActionBar";
import { FormColumnLayout } from "@servicenow/react-components/FormColumnLayout";

interface Props {
  incidentId: string;
  onBack: () => void;
}

export default function IncidentDetail({ incidentId, onBack }: Props) {
  return (
    <div className="campus-app">
      <div className="campus-header">
        <h1 className="section-title">Incident Detail</h1>
        <span className="nav-link" onClick={onBack} role="button" tabIndex={0}>
          &larr; Back to Incidents
        </span>
      </div>
      <RecordProvider table="incident" sysId={incidentId} isReadOnly={false}>
        <FormActionBar />
        <FormColumnLayout />
      </RecordProvider>
    </div>
  );
}
